// Contrato determinista para las olas avanzadas de LUNA.
// Se ejecuta en un workflow staging sin credenciales ni servicios externos.
// No procesa ni persiste texto completo, binarios, PII o transcripciones.

const input = $json || {};
const feature = String(input.feature || 'media|calendar|pdf|multichannel|followup').trim().toLowerCase();
const allowed = new Set(['media', 'calendar', 'pdf', 'multichannel', 'followup']);
const validFeature = allowed.has(feature);
const bool = (v) => v === true || v === 1 || String(v || '').toLowerCase() === 'true';
const hasExplicitConsent = bool(input.consent) || /\b(acepto|confirmo|sí|si|autoriza|autorizo)\b/i.test(String(input.text || ''));
const result = {
  schema_version: '1.0',
  feature: validFeature ? feature : 'unknown',
  active: false,
  staging_only: true,
  external_call: false,
  pii_persisted: false,
  status: 'blocked_until_staging_approval',
  reason_code: validFeature ? 'STAGING_CONTRACT_READY' : 'FEATURE_NOT_ALLOWED',
  fallback: 'Puedo ayudarte mejor si me escribes qué necesitas resolver y a qué se dedica tu negocio.',
};

if (feature === 'media') {
  const mime = String(input.mime_type || '').toLowerCase();
  const supported = /^(audio|image)\//.test(mime);
  result.status = supported ? 'staging_media_contract_ready' : 'fallback_required';
  result.reason_code = supported ? 'MEDIA_MIME_ACCEPTED_NO_PROVIDER_CALL' : 'MEDIA_MIME_UNSUPPORTED';
}
if (feature === 'calendar') {
  result.status = hasExplicitConsent ? 'pending_confirmation' : 'consent_required';
  result.appointment_status = hasExplicitConsent ? 'requested' : 'none';
  result.appointment_timezone = 'America/Bogota';
  result.reason_code = hasExplicitConsent ? 'CALENDAR_REQUEST_STAGED' : 'CALENDAR_CONSENT_REQUIRED';
}
if (feature === 'pdf') {
  const ready = bool(input.discovery_done) && bool(input.solution_confirmed) && bool(input.catalog_ready) && bool(input.proposal_requested);
  result.status = ready ? 'staging_pdf_contract_ready' : 'preconditions_required';
  result.reason_code = ready ? 'PDF_PRECONDITIONS_MET_NO_FILE_CREATED' : 'PDF_PRECONDITIONS_MISSING';
}
if (feature === 'multichannel') {
  const channel = String(input.channel || '').toLowerCase();
  result.channel = channel || 'whatsapp';
  result.status = channel === 'whatsapp' ? 'whatsapp_adapter_ready' : 'adapter_not_active';
  result.reason_code = channel === 'whatsapp' ? 'WHATSAPP_ONLY_ACTIVE_CHANNEL' : 'CHANNEL_DISABLED';
}
if (feature === 'followup') {
  result.active = false;
  result.dry_run = true;
  result.max_per_run = 3;
  result.status = 'dry_run_only';
  result.reason_code = 'FOLLOWUP_REAL_SEND_BLOCKED';
}

return [{ json: result }];
